package com.bank.governance.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates all valid nested approval bracketings (balanced parentheses).
public class ParenthesesService {
    private static final Logger log = Logger.getLogger(ParenthesesService.class.getName());

    public List<String> allBalanced(int n) {
        List<String> result = new ArrayList<>();
        backtrack(n, 0, 0, new StringBuilder(), result);
        log.info(() -> "Generated " + result.size() + " valid bracketings for n=" + n);
        return result;
    }

    private void backtrack(int n, int openCount, int closeCount,
                           StringBuilder current, List<String> result) {
        if (current.length() == 2 * n) {
            result.add(current.toString());
            log.fine(() -> "Completed bracketing " + current);
            return;
        }
        // Place an open if we still have opens available.
        if (openCount < n) {
            current.append('(');
            backtrack(n, openCount + 1, closeCount, current, result);
            current.deleteCharAt(current.length() - 1); // backtrack
        }
        // Place a close only if it would match an existing open.
        if (closeCount < openCount) {
            current.append(')');
            backtrack(n, openCount, closeCount + 1, current, result);
            current.deleteCharAt(current.length() - 1); // backtrack
        }
    }
}
